import React from 'react';

export const VICO_LOGO_BASE64 = 'data:image/png;base64,';

export interface VicoLogoProps {
  className?: string;
  height?: number | string;
  width?: number | string;
  alt?: string;
}

export function VicoLogo({ className = 'h-9 w-auto object-contain', height, width, alt = 'ViCO Logo' }: VicoLogoProps) {
  return (
    <img
      src={VICO_LOGO_BASE64}
      alt={alt}
      className={className}
      style={{ height, width }}
    />
  );
}

export default VicoLogo;
